function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each amount is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > Math.floor((nums.length + 1) / 2)) return 'k must be between 1 and (nums.length + 1) / 2.';
  return null;
}

