function minCapability(nums, k) {
  let low = Math.min(...nums);
  let high = Math.max(...nums);
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let robbed = 0;
    let i = 0;
    while (i < nums.length) {
      if (nums[i] <= mid) {
        robbed++;
        i += 2;
      } else {
        i++;
      }
    }
    if (robbed >= k) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

