function minCapability(nums, k) {
  // Try each distinct amount as the cap, smallest first, and count the most houses a DP can rob under it.
  const caps = [...new Set(nums)].sort((a, b) => a - b);
  for (const cap of caps) {
    let prev2 = 0, prev1 = 0;
    for (const amount of nums) {
      const cur = amount <= cap ? Math.max(prev1, prev2 + 1) : prev1;
      prev2 = prev1;
      prev1 = cur;
    }
    if (prev1 >= k) return cap;
  }
  return -1;
}

