function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 10);
    const top = rand() < 0.5 ? 5 : 100;
    const nums = Array.from({ length: n }, () => pick(1, top));
    return [nums, pick(1, Math.floor((n + 1) / 2))];
  }
  const n = pick(1500, 2000);
  const top = rand() < 0.3 ? 1000 : 1000000000;
  const nums = Array.from({ length: n }, () => pick(1, top));
  return [nums, pick(1, Math.floor((n + 1) / 2))];
}
